base AS (
  SELECT id, coalesce(settings_json, '{}'::jsonb) AS sj
  FROM public.site_settings
  ORDER BY updated_at DESC NULLS LAST
  LIMIT 1
)
UPDATE public.site_settings AS s
SET
  settings_json = jsonb_set(base.sj, '{servicesPage}', payload.services_page, true),
  updated_at = now()
FROM base, payload
WHERE s.id = base.id;

COMMENT ON COLUMN public.site_settings.settings_json IS
  'Full SiteSettings document. Includes homepage, aboutPage, contactPage, servicesPage (Build/Grow/Transform/Support), projectRecords, cvConfig, and announcement fields.';
